// BattleCruiser — 16.6: gestión de Presentaciones (crear, editar, activar/desactivar).
(function(){
'use strict';
if(window.__BC166)return;window.__BC166=true;
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
function permiso(){return typeof tienePermiso==='function' && (tienePermiso('productos','crear')||tienePermiso('productos','editar')||tienePermiso('configuracion','editar')||tienePermiso('catalogos','editar_any'));}
function install(){var tab=document.getElementById('tab-config');if(!tab||!permiso()||document.getElementById('bc166-presentaciones'))return false;var box=document.createElement('div');box.id='bc166-presentaciones';box.className='cc-bloque';box.innerHTML='<h3>Presentaciones</h3><p class="muted">Presentaciones comerciales usadas en compras y ventas. El factor de conversión se define al asociarlas a cada producto.</p><div class="inline-form" style="display:flex;gap:8px;flex-wrap:wrap"><input id="bc166-nombre" placeholder="Nueva presentación, ej. Caja x 24"><button type="button" id="bc166-crear">Crear presentación</button></div><div id="bc166-lista" class="lista" style="margin-top:10px"><p class="lista-estado">Cargando…</p></div><p id="bc166-msg" class="msg"></p>';tab.appendChild(box);box.querySelector('#bc166-crear').onclick=crear;refrescar();return true;}
function msg(t,ok){var e=document.getElementById('bc166-msg');if(e){e.textContent=t||'';e.className='msg'+(ok===true?' success':ok===false?' error':'');}}
async function rows(){try{var r=await client.from('presentaciones').select('id,nombre,activo,created_at').order('nombre');if(r.error)throw r.error;return r.data||[];}catch(e){console.warn('[BC166] presentaciones',e);return[];}}
async function refrescar(){var el=document.getElementById('bc166-lista');if(!el)return;var r=await rows();if(!r.length){el.innerHTML='<p class="lista-estado">No hay presentaciones creadas.</p>';return;}el.innerHTML=r.map(function(x){return '<div class="lista-item" data-pid="'+esc(x.id)+'"><span><strong>'+esc(x.nombre)+'</strong> <span class="muted">'+(x.activo?'Activa':'Inactiva')+'</span></span><span style="display:flex;gap:6px"><button type="button" data-edit="1">Editar</button><button type="button" data-toggle="1">'+(x.activo?'Desactivar':'Activar')+'</button></span></div>';}).join('');el.querySelectorAll('[data-edit]').forEach(function(b){b.onclick=function(){var id=b.closest('[data-pid]').dataset.pid;var x=r.find(function(z){return String(z.id)===String(id)});if(!x)return;var n=prompt('Nombre de la presentación',x.nombre);if(n&&n.trim()&&n.trim()!==x.nombre)editar(id,n.trim());};});el.querySelectorAll('[data-toggle]').forEach(function(b){b.onclick=function(){var id=b.closest('[data-pid]').dataset.pid;var x=r.find(function(z){return String(z.id)===String(id)});if(x)cambiar(id,!x.activo);};});}
async function crear(){var e=document.getElementById('bc166-nombre'),n=(e&&e.value||'').trim();if(!n){msg('Escribí un nombre.',false);return;}try{var r=await client.rpc('crear_presentacion',{p_nombre:n,p_idempotency_key:crypto.randomUUID()});if(r.error)throw r.error;if(e)e.value='';msg('Presentación creada.',true);await refrescar();}catch(err){msg(err.message||'No se pudo crear la presentación.',false);}}
async function editar(id,n){try{var r=await client.rpc('actualizar_presentacion',{p_presentacion_id:id,p_nombre:n,p_idempotency_key:crypto.randomUUID()});if(r.error)throw r.error;msg('Presentación actualizada.',true);await refrescar();}catch(err){msg(err.message||'No se pudo actualizar.',false);}}
async function cambiar(id,activo){try{var r=await client.rpc('cambiar_estado_presentacion',{p_presentacion_id:id,p_activo:activo,p_idempotency_key:crypto.randomUUID()});if(r.error)throw r.error;msg(activo?'Presentación activada.':'Presentación desactivada.',true);await refrescar();}catch(err){msg(err.message||'No se pudo cambiar el estado.',false);}}
function boot(){if(install())return;[300,800,1600,3000].forEach(function(ms){setTimeout(install,ms)});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
window.__BC166_verify=function(){return{panel:!!document.getElementById('bc166-presentaciones'),create:!!document.getElementById('bc166-crear'),list:!!document.getElementById('bc166-lista')}};
})();
